namespace ghidra.app.plugin.core.debug.stack;



using ghidra.debug.api.tracemgr;
using ghidra.framework.cmd;
using ghidra.framework.plugintool;
using ghidra.pcode.exec.DebuggerPcodeUtils;
using ghidra.trace.model;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * A command to unwind as much of the stack as possible and annotate the resulting frame in the
 * dynamic listing
 */
public class UnwindStackCommand : BackgroundCommand<Trace> {

	private PluginTool tool;
	private DebuggerCoordinates where;

	public UnwindStackCommand(PluginTool tool, DebuggerCoordinates where) : base("Unwind Stack", false, true, false)
    {
		this.tool = tool;
		this.where = where;
	}

	/* @Override */
	public bool applyTo(Trace obj, TaskMonitor monitor) {
		try {
			StackUnwinder unwinder = new StackUnwinder(tool, where.getPlatform());
			int prevParamSize = 0;
			Map<Integer, AnalysisUnwoundFrame<WatchValue>> frames =
				unwinder.getFrames(where, monitor);
			for (int i = 0; i < frames.size(); i++) {
				AnalysisUnwoundFrame<WatchValue> frame = frames.get(i);
				if (frame != null) {
					UnwindInfo info = frame.getUnwindInfo();
					if (info != null && info.error() == null) {
						frame.applyToListing(prevParamSize, monitor);
						prevParamSize = info.computeParamSize();
					}
					else {
						tool.setStatusInfo(frame.getError().getMessage());
					}
				}
			}
			return true;
		}
		catch (CancelledException e) {
			return true;
		}
	}
}
